flowchart TD
  subgraph External ["External Level (Views)"]
    V1["View 1: Customer Portal"]
    V2["View 2: Billing & Audit"]
  end

  subgraph Logical ["Logical / Conceptual Level"]
    CS["Logical Schema\nCustomers, Orders, Invoices"]
  end

  subgraph Internal ["Internal Level (Storage)"]
    IS["Internal Schema\nHeap files, B+ Trees, Columnar Indexes"]
  end

  V1 -->|External/Logical Mapping| CS
  V2 -->|External/Logical Mapping| CS
  CS -->|Logical/Internal Mapping| IS

  classDef ext fill:#f0fdf4,stroke:#16a34a,stroke-width:1.5px;
  classDef log fill:#ede9fe,stroke:#6366f1,stroke-width:2px;
  classDef int fill:#f8fafc,stroke:#475569,stroke-width:1.5px;
  class V1,V2 ext;
  class CS log;
  class IS int;
